function rounded(c,x,y,w,h,r){c.beginPath();c.roundRect(x,y,w,h,r)}
function drawCar(c,x,y,angle,color,scale=1,shape=0,damage=0,spoiler=0){c.save();c.translate(x,y);c.rotate(angle);c.scale(scale,scale);c.shadowColor='#0009';c.shadowBlur=10;c.shadowOffsetY=5;
let widths=[17,16,16,19,17,18,17,18,16,19],lens=[38,42,45,46,39,42,41,43,40,44],w=widths[shape]||17,l=lens[shape]||40;
// wheels
c.fillStyle='#111513';for(let sy of [-1,1])for(let sx of [-1,1]){rounded(c,-l*.28+(sx<0?-w*.57:w*.19),sy*(w*.42)-3, l*.2,6,2);c.fill()}
c.shadowBlur=4;c.shadowOffsetY=1;
// spoiler
if(spoiler){c.fillStyle='#1a2020';c.fillRect(-l*.39,-w*.57,6,2);c.fillRect(-l*.39,w*.48,6,2);c.fillStyle='#242b2a';c.fillRect(-l*.48,-w*.63,9,2.4)}
// soft deformed shell
c.beginPath();c.moveTo(l*.48,0);c.quadraticCurveTo(l*.45,-w*.38,l*.28,-w*.49);c.lineTo(-l*.25,-w*.48);c.quadraticCurveTo(-l*.42,-w*.44,-l*.48,-w*.24);c.lineTo(-l*.49,w*.24);c.quadraticCurveTo(-l*.41,w*.44,-l*.25,w*.48);c.lineTo(l*.28,w*.49);c.quadraticCurveTo(l*.46,w*.38,l*.48,0);c.closePath();c.fillStyle=color;c.fill();c.strokeStyle='#ffffff55';c.lineWidth=1;c.stroke();
