if(damage>5){c.fillStyle='#161a18';for(let i=0;i<Math.min(5,Math.floor(damage/13));i++){let dx=-l*.3+(i%3)*l*.2,dy=(i%2?1:-1)*w*.36;c.beginPath();c.ellipse(dx,dy,2+damage*.025,1.3,dx,0,Math.PI*2);c.fill()}if(damage>45){c.strokeStyle='#292321';c.lineWidth=1.5;c.beginPath();c.moveTo(l*.36,-w*.3);c.lineTo(l*.2,-w*.05);c.lineTo(l*.3,w*.18);c.stroke()}}
// glass cabin
c.fillStyle='#1b3535';c.beginPath();c.moveTo(l*.18,0);c.lineTo(l*.08,-w*.35);c.lineTo(-l*.22,-w*.34);c.lineTo(-l*.3,-w*.2);c.lineTo(-l*.3,w*.2);c.lineTo(-l*.22,w*.34);c.lineTo(l*.08,w*.35);c.closePath();c.fill();c.strokeStyle='#ffffff35';c.stroke();c.fillStyle='#c9dcd544';c.fillRect(-l*.06,-w*.31,2,w*.62);
