c.fillStyle='#fff0c1';c.fillRect(l*.39,-w*.32,3,4);c.fillRect(l*.39,w*.14,3,4);c.fillStyle='#fb5746';c.fillRect(-l*.43,-w*.3,2,4);c.fillRect(-l*.43,w*.17,2,4);
