function roadCenter(v){return Math.round(v/500)*500}function onRoad(x,y){let dx=Math.abs(x-roadCenter(x)),dy=Math.abs(y-roadCenter(y));return dx<65||dy<65}
function initBots(){bots=[];for(let i=0;i<24;i++){let horizontal=Math.random()<.54,road=(Math.floor(rand(-5,6))*500),pos=rand(-1800,1800);bots.push({x:horizontal?pos:road+(Math.random()<.5?-18:18),y:horizontal?road+(Math.random()<.5?-18:18):pos,a:horizontal?(Math.random()<.5?0:Math.PI):Math.random()<.5?Math.PI/2:-Math.PI/2,v:rand(8,20),color:['#ee785f','#62a8a2','#eee9db','#ac91d3','#5481ae','#e8ae54'][i%6],shape:Math.floor(rand(0,10)),horn:0})}}initBots();
function drawWorld(){ctx.clearRect(0,0,W,H);let night=(Math.cos((dayTime-13)/24*Math.PI*2)+1)/2;let sky=ctx.createLinearGradient(0,0,0,H);sky.addColorStop(0,night>.65?'#17232a':'#84aa9d');sky.addColorStop(.52,night>.65?'#344344':'#a9b69b');sky.addColorStop(1,'#667968');ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);
ctx.save();ctx.translate(W/2-cam.x,H/2-cam.y);let l=cam.x-W/2-250,r=cam.x+W/2+250,t=cam.y-H/2-250,b=cam.y+H/2+250;
// neighborhood lots
for(let gx=Math.floor(l/500)-1;gx<=Math.ceil(r/500)+1;gx++)for(let gy=Math.floor(t/500)-1;gy<=Math.ceil(b/500)+1;gy++){let bx=gx*500,by=gy*500;let seed=Math.abs((gx*73856093)^(gy*19349663));ctx.fillStyle=seed%3?'#71816f':'#788573';ctx.fillRect(bx+62,by+62,376,376);ctx.fillStyle='#82907a';ctx.fillRect(bx+65,by+65,370,370);
// building blocks
for(let k=0;k<4;k++){let sx=bx+95+(k%2)*166,sy=by+94+Math.floor(k/2)*164,ww=118+(seed+k*7)%39,hh=104+(seed>>k)%40;let palette=['#727d78','#a49b85','#818c83','#9c907a','#687c7a'];ctx.fillStyle='#435047';ctx.fillRect(sx+7,sy+9,ww,hh);ctx.fillStyle=palette[(seed+k)%palette.length];ctx.fillRect(sx,sy,ww,hh);ctx.fillStyle='#ffffff14';ctx.fillRect(sx+7,sy+5,ww-14,4);ctx.fillStyle='#323e3d';for(let wx=sx+13;wx<sx+ww-7;wx+=21)for(let wy=sy+14;wy<sy+hh-8;wy+=22)ctx.fillRect(wx,wy,8,7);ctx.fillStyle='#566a54';ctx.fillRect(sx-8,sy+hh-5,ww+16,8)}
for(let k=0;k<7;k++){let tx=bx+78+((seed+k*83)%340),ty=by+78+((seed>>k+k*31)%340);ctx.fillStyle='#536751';ctx.beginPath();ctx.arc(tx+2,ty+3,11,0,Math.PI*2);ctx.fill();ctx.fillStyle=['#687d62','#798968','#5e765f'][k%3];ctx.beginPath();ctx.arc(tx,ty,10,0,Math.PI*2);ctx.fill()}}
// roads grid
ctx.fillStyle='#424a49';for(let gx=Math.floor(l/500)-1;gx<=Math.ceil(r/500)+1;gx++)ctx.fillRect(gx*500-67,t,134,b-t);for(let gy=Math.floor(t/500)-1;gy<=Math.ceil(b/500)+1;gy++)ctx.fillRect(l,gy*500-67,r-l,134);
// road shoulders and markings
ctx.strokeStyle='#bac1aa38';ctx.lineWidth=2;ctx.setLineDash([]);for(let gx=Math.floor(l/500)-1;gx<=Math.ceil(r/500)+1;gx++){ctx.beginPath();ctx.moveTo(gx*500-61,t);ctx.lineTo(gx*500-61,b);ctx.moveTo(gx*500+61,t);ctx.lineTo(gx*500+61,b);ctx.stroke();ctx.strokeStyle='#d7cf9f77';ctx.setLineDash([14,18]);ctx.beginPath();ctx.moveTo(gx*500,t);ctx.lineTo(gx*500,b);ctx.stroke();ctx.setLineDash([]);ctx.strokeStyle='#bac1aa38'}for(let gy=Math.floor(t/500)-1;gy<=Math.ceil(b/500)+1;gy++){ctx.beginPath();ctx.moveTo(l,gy*500-61);ctx.lineTo(r,gy*500-61);ctx.moveTo(l,gy*500+61);ctx.lineTo(r,gy*500+61);ctx.stroke();ctx.strokeStyle='#d7cf9f77';ctx.setLineDash([14,18]);ctx.beginPath();ctx.moveTo(l,gy*500);ctx.lineTo(r,gy*500);ctx.stroke();ctx.setLineDash([]);ctx.strokeStyle='#bac1aa38'}
// water channels, park accents
for(let n=-2;n<=2;n++){let px=n*1000+260;if(px>l&&px<r){ctx.fillStyle='#426b6a';ctx.fillRect(px,Math.max(t,-2300),30,4600);ctx.fillStyle='#72917d';ctx.fillRect(px-6,Math.max(t,-2300),5,4600);ctx.fillRect(px+31,Math.max(t,-2300),5,4600)}}
// mission checkpoints
if(quest&&quest.active){let target=quest.stage===0?quest.pick:quest.drop;let pulse=1+Math.sin(elapsed*4)*.1;ctx.strokeStyle='#c8f45a';ctx.lineWidth=3;ctx.beginPath();ctx.arc(target.x,target.y,23*pulse,0,Math.PI*2);ctx.stroke();ctx.fillStyle='#c8f45a';ctx.beginPath();ctx.arc(target.x,target.y,5,0,Math.PI*2);ctx.fill();ctx.font='bold 11px monospace';ctx.fillText(quest.stage===0?'PICK UP':'DELIVER',target.x+30,target.y-18)}
// bots
for(let bot of bots)if(Math.abs(bot.x-cam.x)<W&&Math.abs(bot.y-cam.y)<H)drawCar(ctx,bot.x,bot.y,bot.a,bot.color,.9,bot.shape,0,0);
// skid marks
ctx.strokeStyle='#17201e72';ctx.lineWidth=3;for(let s of skid){ctx.beginPath();ctx.moveTo(s.x,s.y);ctx.lineTo(s.x-s.dx*1.6,s.y-s.dy*1.6);ctx.stroke()}
