let jitter=player.bump>0?rand(-player.bump,player.bump):0;drawCar(ctx,player.x+jitter,player.y+jitter,player.a,setup.paint,1.15,car.shape,player.damage,setup.spoiler);
ctx.restore();
// atmosphere overlay
