if(weather==='rain'||weather==='storm'||weather==='flood'){ctx.strokeStyle=weather==='storm'?'#d8e6e666':'#dce9e94a';ctx.lineWidth=1;for(let i=0;i<100;i++){let x=(i*173+elapsed*250)%W,y=(i*97+elapsed*510)%H;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x-7,y+16);ctx.stroke()}}
