if(weather==='frost'){ctx.fillStyle='#b8d5df18';ctx.fillRect(0,0,W,H)}
}

function startQuest(type='delivery'){let x=player.x,y=player.y;let dir=(Math.random()*4)|0,dx=[1,0,-1,0][dir],dy=[0,1,0,-1][dir];let pick={x:Math.round((x+dx*520)/500)*500,y:Math.round((y+dy*520)/500)*500};let drop={x:Math.round((pick.x+dy*700)/500)*500,y:Math.round((pick.y-dx*700)/500)*500};let configs={delivery:{title:'The Long Way Home',desc:'Pick up a parcel, then deliver it across the district before the clock runs out.',reward:480,time:90,badge:'01'},sprint:{title:'Crosstown sprint',desc:'Thread through three neon checkpoints. Keep your speed up and hit every gate.',reward:650,time:65,badge:'02'},smash:{title:'Crash test run',desc:'A controlled chaos job. Rack up 2,500 impact points before the timer expires.',reward:350,time:75,badge:'03'}};let cfg=configs[type];quest={type,...cfg,pick,drop,stage:0,active:true,score:0,checkpoints:type==='sprint'?0:0};questTime=cfg.time;questIndex++;$('#missionBadge').textContent=cfg.badge;$('#missionTitle').textContent=cfg.title;$('#missionDesc').textContent=cfg.desc;$('#missionReward').textContent=`+$${cfg.reward}`;$('#missionStep').textContent=type==='smash'?'IMPACT SCORE 0 / 2500':'HEAD TO PICKUP';$('#missionProgress').style.width='0%';$$('.job').forEach(j=>j.classList.toggle('active',j.dataset.job===type));toast(`${cfg.title.toUpperCase()} · CONTRACT ACCEPTED`);}
function updateQuest(dt){if(!quest||!quest.active)return;questTime-=dt;let target=quest.stage===0?quest.pick:quest.drop;let dist=Math.hypot(player.x-target.x,player.y-target.y);if(quest.type==='smash'){quest.score=Math.min(2500,Math.floor(player.damage*32+combo*25));$('#missionStep').textContent=`IMPACT SCORE ${quest.score} / 2500`;$('#missionProgress').style.width=(quest.score/2500*100)+'%';if(quest.score>=2500){finishQuest(true);return}}
else if(dist<43){if(quest.type==='sprint'){quest.checkpoints++;if(quest.checkpoints>=3){finishQuest(true);return}quest.pick={x:Math.round((quest.pick.x+rand(-750,750))/500)*500,y:Math.round((quest.pick.y+rand(-750,750))/500)*500};toast(`CHECKPOINT ${quest.checkpoints}/3 · KEEP MOVING`)}else if(quest.stage===0){quest.stage=1;toast('PARCEL SECURED · DELIVER IT');$('#missionStep').textContent='PARCEL SECURED · DELIVER IT';}else{finishQuest(true);return}}
if(quest.type!=='smash'){let total=quest.type==='sprint'?3:2,done=quest.type==='sprint'?quest.checkpoints:quest.stage;$('#missionProgress').style.width=(done/total*100)+'%';if(quest.type==='delivery')$('#missionStep').textContent=quest.stage===0?`PICKUP · ${Math.round(dist)} M`:`DELIVERY · ${Math.round(dist)} M`}
if(questTime<=0){finishQuest(false);return}if(Math.floor(questTime)!==Math.floor(questTime+dt))$('#missionReward').textContent=`+$${quest.reward} · ${Math.ceil(questTime)}s`}
function finishQuest(won){quest.active=false;if(won){let payout=quest.reward+Math.max(0,Math.floor(questTime*3));money+=payout;saveSetup();$('#moneyTop').textContent='$'+money.toLocaleString();$('#missionStep').textContent='CONTRACT COMPLETE';$('#missionProgress').style.width='100%';toast(`CONTRACT COMPLETE · +$${payout.toLocaleString()}`);if(soundOn)beep(680,.16)}else{$('#missionStep').textContent='CONTRACT EXPIRED';toast('CONTRACT EXPIRED · TRY ANOTHER ROUTE')}$('#missionReward').textContent=won?'PAID':'RETRY';}
function toast(msg){let el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2300)}
function updateWeather(w){weather=w;let info=weatherInfo[w];$('#weatherName').textContent=info[0];$('#weatherDesc').textContent=info[1];$('#weatherIcon').textContent=info[2];$$('.wx').forEach(x=>x.classList.toggle('active',x.dataset.weather===w));}
$$('.wx').forEach(b=>b.onclick=()=>updateWeather(b.dataset.weather));let wxList=['clear','rain','snow','storm','frost','tornado','flood'];$('#weatherBtn').onclick=()=>{updateWeather(wxList[(wxList.indexOf(weather)+1)%wxList.length]);toast('WEATHER: '+weatherInfo[weather][0].toUpperCase())};
function setOverlay(open){$('#overlay').classList.toggle('hidden',!open);if(open)drawPreview()}
$('#startBtn').onclick=()=>{setOverlay(false);running=true;if(!quest||!quest.active)startQuest('delivery');initAudio();last=performance.now()};$('#closeModal').onclick=()=>{setOverlay(false);running=true;initAudio();if(!quest)startQuest('delivery')};$('#garageBtn').onclick=()=>setOverlay(true);$('#resetBtn').onclick=()=>{player.x=Math.round(player.x/500)*500;player.y=Math.round(player.y/500)*500;player.v=0;player.damage=0;player.engine=100;toast('VEHICLE REPAIRED · DAMAGE CLEARED')};
$$('.job').forEach(j=>j.onclick=()=>{if(!running){setOverlay(false);running=true}startQuest(j.dataset.job);initAudio()});$('#missionTitle').onclick=()=>{if(!running){setOverlay(false);running=true;initAudio()}startQuest(quest?.type==='delivery'?'sprint':'delivery')};$('#soundBtn').onclick=()=>{soundOn=!soundOn;$('#soundBtn').textContent=soundOn?'♫':'♩';if(!soundOn&&audio)audio.suspend();else if(audio)audio.resume();else initAudio();toast(soundOn?'ENGINE AUDIO ON':'ENGINE AUDIO OFF')};
function initAudio(){if(!soundOn||audio)return;try{audio=new(window.AudioContext||window.webkitAudioContext)();engineOsc=audio.createOscillator();engineOsc.type=setup.brand==='Tesla'?'sine':setup.brand==='Ferrari'||setup.brand==='Lamborghini'?'sawtooth':'triangle';engineGain=audio.createGain();engineGain.gain.value=.0001;engineOsc.connect(engineGain);engineGain.connect(audio.destination);engineOsc.start()}catch(e){}}
function beep(freq,duration){if(!audio||!soundOn)return;let o=audio.createOscillator(),g=audio.createGain();o.frequency.value=freq;g.gain.setValueAtTime(.055,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+duration)}
function updateAudio(){if(!audio||!engineOsc)return;let rev=clamp(Math.abs(player.v)/car.speed,0,1);engineOsc.frequency.setTargetAtTime((setup.brand==='Tesla'?150:54)+rev*(setup.brand==='Tesla'?500:250)+setup.turbo*12,audio.currentTime,.08);engineGain.gain.setTargetAtTime(player.v>.5?.02+rev*.07:.0001,audio.currentTime,.1)}
function setKey(e,on){let k=e.key.toLowerCase();if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(k))e.preventDefault();keys[k]=on;if(on&&!e.repeat){if(k==='g')setOverlay($('#overlay').classList.contains('hidden'));if(k==='r')$('#resetBtn').click();if(k==='w'&&!['w','a','s','d','arrowup','arrowdown'].includes(k))$('#weatherBtn').click();if(k==='escape')setOverlay(!$('#overlay').classList.contains('hidden'))}}addEventListener('keydown',e=>setKey(e,true));addEventListener('keyup',e=>setKey(e,false));
