function update(dt){elapsed+=dt;dayTime=(dayTime+dt*.035)%24;player.bump=Math.max(0,player.bump-dt*28);collisionCooldown=Math.max(0,collisionCooldown-dt);const throttle=keys.w||keys.arrowup||touch.gas,brake=keys.s||keys.arrowdown||touch.brake,left=keys.a||keys.arrowleft||touch.left,right=keys.d||keys.arrowright||touch.right,hand=keys[' '];let traction=setup.tire==='sport'?1.13:setup.tire==='dirt'?.94:setup.tire==='drift'?.83:1;traction*=weather==='rain'?.77:weather==='snow'?.56:weather==='frost'?.48:weather==='storm'?.68:weather==='flood'?.61:1;let speedFactor=1+setup.turbo*.16,max=car[2]*speedFactor/3.6;if(throttle)player.v+=32*car[1]*speedFactor*dt;if(brake)player.v-=player.v>1?55*dt:22*dt;player.v*=Math.pow(hand?.965:.986,dt*60);if(!throttle&&!brake)player.v*=Math.pow(.992,dt*60);player.v=Math.max(-max*.25,Math.min(max,player.v));let steer=(left?-1:0)+(right?1:0);player.a+=steer*dt*(.85+Math.min(1.3,Math.abs(player.v)/35))*traction*(player.v<0?-1:1);let grip=traction*(hand?.48:1);player.x+=Math.cos(player.a)*player.v*dt;player.y+=Math.sin(player.a)*player.v*dt;let roadGrip=onRoad(player.x,player.y)?1:.67;if(!onRoad(player.x,player.y))player.v*=Math.pow(.994,dt*60);player.drift+=(Math.abs(steer)*Math.abs(player.v)/35*grip-player.drift)*dt*3;player.drift=Math.max(0,Math.min(100,player.drift));if(Math.abs(player.v)>15&&player.drift>25&&Math.random()<dt*12){skids.push({x:player.x-Math.cos(player.a)*15,y:player.y-Math.sin(player.a)*15,dx:Math.sin(player.a)*5,dy:-Math.cos(player.a)*5});if(skids.length>500)skids.shift()}
