cam.x+=(player.x-cam.x)*Math.min(1,dt*5);cam.y+=(player.y-cam.y)*Math.min(1,dt*5);let kmh=Math.round(Math.abs(player.v)*3.6);$('#bigSpeed').textContent=String(kmh).padStart(3,'0');$('#smallSpeed').textContent=String(kmh).padStart(3,'0');$('#speedMeter').style.width=Math.min(100,kmh/(car[2]*(1+setup.turbo*.16))*100)+'%';$('#engineStat').textContent=player.v>2?''+Math.round(900+Math.abs(player.v)*48)+' RPM':'IDLE';$('#gear').textContent=player.v<1?'N':player.v<14?'1':player.v<28?'2':player.v<45?'3':player.v<65?'4':player.v<90?'5':'6';$('#clock').textContent=String(Math.floor(dayTime)%24).padStart(2,'0')+':'+String(Math.floor((dayTime%1)*60)).padStart(2,'0');if(audio&&osc){osc.frequency.setTargetAtTime(48+Math.abs(player.v)*2.1+(throttle?35:0),audio.currentTime,.08);if(gain)gain.gain.setTargetAtTime(soundOn?(.012+Math.abs(player.v)/3000):0,audio.currentTime,.1)}$('#moneyTop').textContent='$'+money.toLocaleString()}
